import os

from google.cloud import storage
from storage_models import StorageConfig

def get_storage_client(config: Optional[StorageConfig] = None) -> storage.Client:
    if config:
        return storage.Client(project=config.project_id)
    else:
        project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
        bucket_name = os.getenv("GOOGLE_CLOUD_STORAGE_BUCKET")
        if not project_id or not bucket_name:
            raise ValueError("Google Cloud project ID and bucket name must be provided in config or GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_STORAGE_BUCKET environment variables.")
        return storage.Client(project=project_id)

def get_bucket_name(config: Optional[StorageConfig] = None) -> str:
    if config:
        return config.bucket_name
    else:
        bucket_name = os.getenv("GOOGLE_CLOUD_STORAGE_BUCKET")
        if not bucket_name:
            raise ValueError("Google Cloud Storage bucket name must be provided in config or GOOGLE_CLOUD_STORAGE_BUCKET environment variable.")
        return bucket_name

from typing import Optional

from storage_client import get_storage_client, get_bucket_name
from storage_models import ListPrefixPayload, StorageConfig

def list_prefix(payload: ListPrefixPayload, config: Optional[StorageConfig] = None) -> dict:
    client = get_storage_client(config)
    bucket_name = get_bucket_name(config)
    bucket = client.bucket(bucket_name)

    blobs = client.list_blobs(bucket, prefix=payload.prefix, delimiter=payload.delimiter)

    object_names = []
    for blob in blobs:
        object_names.append(blob.name)

    prefixes = []
    if payload.delimiter:
        for prefix in blobs.prefixes:
            prefixes.append(prefix)

    return {"object_names": object_names, "prefixes": prefixes}

from typing import Optional

from google.cloud import vision
from storage_client import get_bucket_name
from storage_models import StoredDocumentOcrPayload, StorageConfig

def stored_document_ocr(payload: StoredDocumentOcrPayload, config: Optional[StorageConfig] = None) -> dict:
    client = vision.ImageAnnotatorClient()
    bucket_name = get_bucket_name(config)
    image = vision.Image({"source": {"image_uri": f"gs://{bucket_name}/{payload.object_name}"}})

    response = client.document_text_detection(image=image, image_context=vision.ImageContext(language_hints=payload.language_hints))

    full_text = response.full_text_annotation.text
    pages_text = []
    for page in response.full_text_annotation.pages:
        page_text = []
        for block in page.blocks:
            for paragraph in block.paragraphs:
                for word in paragraph.words:
                    word_text = ''.join([symbol.text for symbol in word.symbols])
                    page_text.append(word_text)
        pages_text.append(' '.join(page_text))

    return {"full_text": full_text, "pages_text": pages_text}

from typing import Optional

from google.cloud import translate
from storage_models import StoredTextTranslatePayload
import os

def stored_text_translate(payload: StoredTextTranslatePayload, config: Optional[StorageConfig] = None) -> dict:
    client = translate.TranslationServiceClient()
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    if config and config.project_id:
        project_id = config.project_id

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided in config or GOOGLE_CLOUD_PROJECT environment variable.")

    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload.text],
            "source_language_code": payload.source_language_code,
            "target_language_code": payload.target_language_code,
            "mime_type": "text/plain",
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translated_text": translations[0] if translations else ""}
